/**
 * ProvisioningResult DTO
 *
 * Returned by connectors after provisioning. Enables the orchestration layer to:
 * 1. Capture attributes generated by the target system (e.g., work email)
 * 2. Push those attributes back to the Hub and to HR
 *
 * Connectors that CAN generate work email (Entra ID, AD) return generatedAttributes.
 * Connectors that CANNOT (Jira, Slack) return generatedAttributes: undefined.
 */

export interface GeneratedAttributes {
  /** Work email assigned by the target system (e.g., firstname.lastname@company.com) */
  mail?: string;
  /** User Principal Name (often same as mail in Entra ID) */
  userPrincipalName?: string;
  /** AD: sAMAccountName (max 20 chars) */
  samAccountName?: string;
  /** AD: Distinguished Name (e.g., CN=John Doe,OU=Users,DC=gov,DC=fi) */
  distinguishedName?: string;
  /** AD: objectGUID (binary, base64 or hex). Optional; may require post-create read. */
  objectGUID?: string;
}

/** Details of UPN resolution (which candidate was chosen) */
export interface UpnResolutionInfo {
  /** The UPN that was used for provisioning */
  chosenUpn: string;
  /** Candidates that were checked (for debugging / Impact Analysis) */
  candidatesChecked: string[];
}

/** What the target did with one requested entitlement change (an operation of the intent). */
export interface ProvisioningOperationResult {
  type: 'group' | 'license' | 'role';
  action: 'add' | 'remove';
  targetId: string;
  /** applied: the target made the change; unchanged: it was already as requested; failed: not made */
  outcome: 'applied' | 'unchanged' | 'failed';
  /** Why the change was not made (outcome failed), as the target or the connector said it */
  reason?: string;
  /** HTTP status of that failure (the connector's exception), absent when it has none */
  status?: number;
}

export interface ProvisioningResult {
  /** Native ID of the user in the target system */
  targetUserId: string;
  /** One result per operation of the intent, when the call had one (Entra ID) */
  operations?: ProvisioningOperationResult[];
  /**
   * Attributes generated by the target system during creation.
   * Only populated by connectors that can generate work email (Entra ID, AD).
   * Jira, Slack, ServiceNow, etc. do not generate email — they consume it.
   */
  generatedAttributes?: GeneratedAttributes;
  /** UPN resolution details (when resolver was used) */
  upnResolution?: UpnResolutionInfo;
}
